/* ── รายชื่อผู้ร่วมงานรายคน (สูงสุด 10 ท่าน) ────────────────────
   เพดาน = จำนวนที่นั่งที่เชิญ (PRESEATS จาก ?n= หรือ ginfo) ถ้าไม่มีก็
   CFG.maxSeats จากหลังบ้าน ถ้าไม่มีอีกก็นับปุ่มที่เรนเดอร์มาให้
   แขกกดเลข k → ขึ้นช่องชื่อครบ k ท่าน + ช่องแพ้อาหารของแต่ละท่าน
   ท่านที่ 1 ใช้ชื่อจากช่อง "ชื่อผู้ร่วมงาน" ด้านบน ไม่ต้องพิมพ์ซ้ำ */
var PARTY_MAX = 10;
var STATIC_CNT = document.querySelectorAll('.seg-cnt button').length || 1;
function seatCap() {
  var n = parseInt(PRESEATS, 10);
  if (!(n > 0)) n = parseInt(CFG.maxSeats, 10);
  if (!(n > 0)) n = STATIC_CNT;
  return Math.max(1, Math.min(n, PARTY_MAX));
}
function partySize() {
  return Math.max(1, Math.min(parseInt(cnt, 10) || 1, seatCap()));
}
function segBind(sel, fn) {
  var btns = document.querySelectorAll(sel + ' button');
  btns.forEach(function (b) {
    b.addEventListener('click', function () {
      sfxTick();                              /* ทุกปุ่มเลือกมีเสียงแน่นอน */
      fn(b);
      btns.forEach(function (x) {
        x.setAttribute('aria-pressed', x === b ? 'true' : 'false');
      });
    });
  });
}
segBind('.seg-att', function (b) {
  att = b.dataset.att;
  var ex = document.getElementById('yesExtra');
  if (ex) ex.classList.toggle('open', att === 'yes');   /* คลี่นุ่ม ๆ ไม่กระตุก */
  renderParty();
});
segBind('.seg-food', function (b) { food = b.dataset.food; });

/* ปุ่มเลือกจำนวน — เชิญ 2 ที่นั่งใช้ปุ่มยาวแบบเดิม, 3 ขึ้นไปเป็นชิปเลข
   สร้างใหม่เฉพาะตอนเพดานเปลี่ยนจริง (ginfo มาช้า) ไม่งั้นโฟกัสจะหลุด */
function buildSeatChips(cap) {
  var seg = document.querySelector('.seg-cnt');
  if (!seg || seg.dataset.cap === String(cap)) return;
  seg.dataset.cap = String(cap);
  seg.classList.toggle('grid', cap > 2);
  var cur = Math.max(1, Math.min(parseInt(cnt, 10) || 1, cap));
  seg.innerHTML = '';
  for (var i = 1; i <= cap; i++) {
    var b = document.createElement('button');
    b.type = 'button';
    b.dataset.cnt = String(i);
    b.setAttribute('aria-pressed', i === cur ? 'true' : 'false');
    if (cap > 2) { b.textContent = String(i); b.setAttribute('aria-label', i + ' ท่าน'); }
    else b.innerHTML = 'มา ' + i + ' ท่าน<i class="en-sub">' +
                       (i === 1 ? 'Just me' : 'With a guest') + '</i>';
    seg.appendChild(b);
  }
  cnt = String(cur);
  segBind('.seg-cnt', function (x) { cnt = x.dataset.cnt; renderParty(); });
}

/* สร้างการ์ดรายชื่อตามจำนวนที่กด — เก็บของที่พิมพ์ไว้แล้วกลับมาเสมอ
   (กด 5 → พิมพ์ครบ → เผลอกด 3 แล้วกด 5 ใหม่ ต้องไม่หายไปไหน) */
var partyKeep = {};
function renderParty() {
  var wrap = document.getElementById('partyWrap');
  if (!wrap) return;
  wrap.querySelectorAll('input').forEach(function (el) { partyKeep[el.id] = el.value; });
  var on = att === 'yes';
  wrap.hidden = !on;
  if (!on) { wrap.innerHTML = ''; return; }
  var k = partySize(), h = '';
  for (var i = 1; i <= k; i++) {
    h += '<div class="party-row"><p class="pr-hd">ท่านที่ ' + i +
         (i === 1 ? ' <b>· ผู้ตอบรับ</b>' : '') + '</p>';
    h += (i === 1)
      ? '<div class="pr-me" id="pn1" data-ph="— กรอกชื่อในช่องด้านบน —"></div>'
      : '<label for="pn' + i + '">ชื่อ-นามสกุล · FULL NAME</label>' +
        '<input id="pn' + i + '" class="pr-name" autocomplete="off" ' +
        'placeholder="ระบุชื่อจริงเพื่อจัดโต๊ะที่นั่ง">';
    h += '<label for="pd' + i + '">อาหารที่ไม่ทาน / แพ้อาหาร · DIETARY</label>' +
         '<input id="pd' + i + '" class="pr-diet" autocomplete="off" ' +
         'placeholder="ไม่มีเว้นว่างได้ · เช่น แพ้กุ้ง">' +
         '</div>';
  }
  wrap.innerHTML = h;
  wrap.querySelectorAll('input').forEach(function (el) {
    if (partyKeep[el.id]) el.value = partyKeep[el.id];
  });
  mirrorHost();
}
function mirrorHost() {                      /* ท่านที่ 1 = ชื่อจากช่องบนสุด */
  var me = document.getElementById('pn1');
  if (me) me.textContent = val('gname');
}
var hostField = document.getElementById('gname');
if (hostField) hostField.addEventListener('input', mirrorHost);

/* ── ฟอร์มปรับตามที่นั่งที่เชิญของแขกแต่ละคน ────────────────────
   เชิญ 1 ที่นั่ง → ซ่อนคำถามจำนวน (มาคนเดียว ไม่มีตัวเลือก)
   เชิญ 2 ที่นั่งขึ้นไป → โชว์ตัวเลือกถึงเพดาน แต่ค่าเริ่มต้นค้างที่ 1 เสมอ
   (จำนวนที่เชิญคือเพดานสิทธิ์ ไม่ใช่คำตอบล่วงหน้า)
   เรียกซ้ำได้ทุกจังหวะ: ตอนเปิดหน้า (n= ในลิงก์) และตอน ginfo ตอบกลับ */
function applySeatsForm() {
  var sb = document.getElementById('seatsBlock');
  var w2 = document.getElementById('g2wrap');
  var dw = document.getElementById('dietWrap');
  if (w2) w2.hidden = true;          /* ช่องผู้ติดตามเดี่ยว → แทนด้วยรายชื่อรายคน */
  if (dw) dw.hidden = true;          /* ช่องแพ้อาหารรวม → แทนด้วยของแต่ละท่าน */
  var cap = seatCap();
  if (cap <= 1) {
    cnt = '1';
    if (sb) sb.hidden = true;
  } else {
    if (sb) sb.hidden = false;
    buildSeatChips(cap);
    var warn = sb && sb.querySelector('.form-warn');
    if (warn) warn.innerHTML = 'เชิญไว้ ' + cap + ' ท่าน (รวมตัวคุณ) · กรอกชื่อให้ครบทุกท่าน<br>' +
      '<i class="en-line">' + cap + ' seats reserved · unlisted guests won\'t be seated</i>';
  }
  renderParty();
}
SEATSFORM = applySeatsForm;
applySeatsForm();

