/* รายชื่อผู้ร่วมงานทั้งคณะ — ท่านที่ 1 คือผู้ตอบรับ (ช่องชื่อด้านบน) */
function party() {
  var k = partySize(), out = [];
  for (var i = 1; i <= k; i++) {
    out.push({ n: (i === 1 ? val('gname') : val('pn' + i)), d: val('pd' + i) });
  }
  return out;
}
function data() {
  var yes = att === 'yes';
  var ppl = yes ? party() : [{ n: val('gname'), d: '' }];
  /* ชื่อรวมช่องเดียว — ชีต/หน้าเช็คอิน/หน้าที่นั่งตัวเดิมอ่านฟิลด์นี้ */
  var name = ppl.map(function (p) { return p.n; })
                .filter(Boolean).join(' และ ');
  /* งด/แพ้ ผูกชื่อไว้ด้วย ไม่งั้นหน้างานไม่รู้ว่าจานไหนของใคร */
  var diet = yes ? ppl.filter(function (p) { return p.d; })
                      .map(function (p, k) { return (p.n || ('ท่านที่ ' + (k + 1))) + ': ' + p.d; })
                      .join(' · ') : '';
  var msg = val('gmsg');
  /* note รวมไว้เผื่อ Apps Script ตัวเก่า — ตัวใหม่ใช้ฟิลด์แยก */
  var parts = [];
  if (yes) { if (food) parts.push('อาหาร: ' + food); if (diet) parts.push('งด/แพ้: ' + diet); }
  if (msg) parts.push(msg);
  if (!myCode) myCode = makeCode();
  return {
    cardId: CFG.cardId || '',
    name: name,
    going: att,
    seats: yes ? String(ppl.length) : '0',
    food: yes ? food : '',
    diet: diet,
    msg: msg,
    note: parts.join(' · '),
    code: CODE || myCode,
    at: new Date().toISOString(),
    /* ฟิลด์ใหม่ — Apps Script ตัวเก่ามองข้ามได้ไม่พัง ตัวใหม่เก็บรายคน */
    guests: yes ? ppl : [],
    guestsText: yes ? ppl.map(function (p, k) {
      return (k + 1) + '. ' + (p.n || '-') + (p.d ? ' (' + p.d + ')' : '');
    }).join('\n') : ''
  };
}

